        <div class="d-flex flex-column flex-lg-row justify-content-between align-items-lg-center mb-3"><div><h5 class="font-weight-bold mb-1">Riwayat penggunaan</h5><div class="small text-muted">Maksimal 500 login terakhir. Password tidak dicatat.</div></div><div class="d-flex flex-column flex-md-row mt-2 mt-lg-0"><select id="slh-app-filter" class="form-control form-control-sm mr-md-2 mb-2 mb-md-0"><option value="">Semua aplikasi</option><?php foreach ($apps as $code => $app): ?><option value="<?= html_escape(strtolower($code)) ?>"><?= html_escape($app['name']) ?></option><?php endforeach ?></select><input id="slh-search" class="form-control form-control-sm" type="search" placeholder="Cari user, akun, atau IP"></div></div>
        <?php if (empty($history)): ?><div class="text-center py-5 text-muted"><i class="fas fa-history fa-2x mb-3 d-block"></i>Belum ada histori login yang terkonfirmasi.</div>
        <?php else: ?><div class="table-responsive"><table class="table table-hover table-sm slh-table" id="slh-table"><thead><tr><th>Waktu login</th><th>Aplikasi tujuan</th><th>User Portal</th><th>Akun aplikasi</th><th>Alamat IP</th><th>Browser/perangkat</th></tr></thead><tbody>
            <?php foreach ($history as $entry): $searchText = strtolower($entry['app_name'] . ' ' . $entry['portal_user'] . ' ' . $entry['account_username'] . ' ' . ($entry['source_ip'] ?? '')); ?><tr data-app="<?= html_escape(strtolower($entry['app_code'])) ?>" data-search="<?= html_escape($searchText) ?>"><td class="text-nowrap"><strong><?= html_escape($entry['login_at']) ?></strong></td><td><span class="badge badge-light"><?= html_escape($entry['app_name']) ?></span><div class="small text-muted"><code><?= html_escape($entry['app_code']) ?></code></div></td><td><?= html_escape($entry['portal_user']) ?><div class="small text-muted"><?= html_escape($entry['auth_source']) ?> #<?= (int)$entry['user_id'] ?></div></td><td><strong><?= html_escape($entry['account_username']) ?></strong></td><td class="text-nowrap"><?= html_escape($entry['source_ip'] ?: '-') ?></td><td><div class="slh-agent" title="<?= html_escape($entry['user_agent'] ?? '') ?>"><?= html_escape($entry['user_agent'] ?: '-') ?></div></td></tr><?php endforeach ?>
        </tbody></table></div><div class="small text-muted" id="slh-result-count"></div><?php endif ?>
