<script>
$(function(){function filterRows(){const app=String($('#slh-app-filter').val()||''),query=String($('#slh-search').val()||'').toLowerCase();let shown=0;$('#slh-table tbody tr').each(function(){const $row=$(this),visible=(!app||String($row.data('app'))===app)&&String($row.data('search')||'').includes(query);$row.toggle(visible);if(visible)shown++;});$('#slh-result-count').text(shown+' histori ditampilkan');}$('#slh-app-filter,#slh-search').on('input change',filterRows);filterRows();});
</script>
